describe('ARIA Landmarks Accessibility Tests', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the application
    });

    it('should have a main landmark region', () => {
        cy.get('main').should('exist');
        cy.get('main').should('have.attr', 'role', 'main');
    });

    it('should have a navigation landmark region', () => {
        cy.get('nav').should('exist');
        cy.get('nav').should('have.attr', 'role', 'navigation');
    });

    it('should not have multiple main landmarks', () => {
        cy.get('main').should('have.length', 1);
    });

    it('should have a complementary landmark region', () => {
        cy.get('aside').should('exist');
        cy.get('aside').should('have.attr', 'role', 'complementary');
    });
});
